SELECT ticker, trade_time, price, last_bid, last_ask
FROM (
  SELECT *, LAST_VALUE(bid IGNORE NULLS) OVER (
    PARTITION BY ticker ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
  ) as last_bid
  FROM combined_trades_quotes
) WHERE is_trade = TRUE;

