# PySpark Arrow Vectorized UDF for Embeddings
from pyspark.sql.functions import pandas_udf
import pandas as pd
@pandas_udf('array<float>')
def generate_embeddings(texts: pd.Series) -> pd.Series:
    from sentence_transformers import SentenceTransformer
    model = SentenceTransformer('all-MiniLM-L6-v2')
    vectors = model.encode(texts.tolist(), normalize_embeddings=True)
    return pd.Series(list(vectors))

embedded_df = df.withColumn('vector', generate_embeddings(col('doc_chunk')))

